import numpy as np
def integral_image(image):
    a=np.asarray(image)
    if a.ndim!=2: raise ValueError
    c=a.astype(np.float64,copy=False).cumsum(0).cumsum(1)
    out=np.zeros((a.shape[0]+1,a.shape[1]+1),dtype=np.float64); out[1:,1:]=c; return out
def rectangle_sum(ii,y0,x0,y1,x1):
    s=np.asarray(ii); h,w=s.shape[0]-1,s.shape[1]-1
    if s.ndim!=2 or not (0<=y0<=y1<=h and 0<=x0<=x1<=w): raise ValueError
    return float(s[y1,x1]-s[y0,x1]-s[y1,x0]+s[y0,x0])

import numpy as np
def patchify(image,patch_size):
    x=np.asarray(image)
    if x.ndim!=3 or patch_size<=0: raise ValueError
    h,w,c=x.shape; p=patch_size
    if h%p or w%p: raise ValueError
    return x.reshape(h//p,p,w//p,p,c).transpose(0,2,1,3,4).reshape(-1,p*p*c)
def unpatchify(patches,image_shape,patch_size):
    q=np.asarray(patches); h,w,c=map(int,image_shape); p=int(patch_size)
    if p<=0 or h%p or w%p: raise ValueError
    n=(h//p)*(w//p)
    if q.shape!=(n,p*p*c): raise ValueError
    return q.reshape(h//p,w//p,p,p,c).transpose(0,2,1,3,4).reshape(h,w,c)

import numpy as np
def mean_multiclass_dice(pred,target,num_classes,ignore_index=None):
    p=np.asarray(pred); t=np.asarray(target)
    if p.shape!=t.shape or num_classes<=0: raise ValueError
    if ignore_index is not None and not (0<=int(ignore_index)<num_classes): raise ValueError
    for a in (p,t):
        if not np.issubdtype(a.dtype,np.integer) or (a.size and ((a<0).any() or (a>=num_classes).any())): raise ValueError
    v=[]
    for c in range(num_classes):
        if ignore_index is not None and c==int(ignore_index): continue
        pm,tm=p==c,t==c; den=int(pm.sum())+int(tm.sum())
        if den: v.append(2.0*float(np.logical_and(pm,tm).sum())/den)
    return float(np.mean(v)) if v else float('nan')

import torch
def label_smoothed_cross_entropy(logits,targets,smoothing=0.1):
    if logits.ndim<2 or logits.shape[-1]<2 or not (0<=smoothing<1) or targets.shape!=logits.shape[:-1]: raise ValueError
    if targets.numel() and ((targets<0).any() or (targets>=logits.shape[-1]).any()): raise ValueError
    lp=torch.log_softmax(logits,dim=-1); tr=lp.gather(-1,targets.long().unsqueeze(-1)).squeeze(-1); oth=lp.sum(-1)-tr
    return (-(1-smoothing)*tr-(smoothing/(logits.shape[-1]-1))*oth).mean()

import numpy as np
def causal_padding_mask(lengths,max_len):
    l=np.asarray(lengths)
    if l.ndim!=1 or not np.issubdtype(l.dtype,np.integer) or max_len<0 or (l.size and ((l<0).any() or (l>max_len).any())): raise ValueError
    q=np.arange(max_len)[None,:,None]; k=np.arange(max_len)[None,None,:]
    return (q<l[:,None,None])&(k<l[:,None,None])&(k<=q)
